-- 0007_documents: private student documents (metadata; the bytes live in private object storage), review of mark sheets /
-- certificates, an append-only access/history log, and evidence links from academic submissions to documents.
-- The database NEVER stores file content or a URL. Storage keys are generated by the server and verified here.

GRANT CREATE ON SCHEMA academics TO cc_auth;    -- temporary: function replacement; revoked at the end
CREATE SCHEMA documents;
REVOKE ALL ON SCHEMA documents FROM PUBLIC;
GRANT USAGE ON SCHEMA documents TO cc_app;
GRANT USAGE, CREATE ON SCHEMA documents TO cc_auth;

ALTER TABLE academic_submissions ADD CONSTRAINT academic_submissions_student_scope UNIQUE (college_id, student_id, id);

CREATE TABLE documents (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  college_id       uuid NOT NULL,
  student_id       uuid NOT NULL,
  kind             text NOT NULL CHECK (kind IN ('RESUME', 'MARKSHEET', 'CERTIFICATE', 'OTHER')),
  original_name    text NOT NULL CHECK (length(original_name) BETWEEN 1 AND 120 AND original_name !~ '[\x00-\x1F\x7F/\\]'),
  content_type     text NOT NULL CHECK (content_type IN ('application/pdf', 'image/png', 'image/jpeg')),
  size_bytes       int  NOT NULL CHECK (size_bytes BETWEEN 1 AND 5242880),
  sha256           text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
  storage_key      text NOT NULL UNIQUE CHECK (storage_key ~ '^c/[0-9a-f-]{36}/s/[0-9a-f-]{36}/[0-9a-f-]{36}$'),
  status           text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'DELETED')),
  -- No malware scanner is wired in yet; the field exists so the state is honest and a scanner can be added later.
  scan_status      text NOT NULL DEFAULT 'NOT_SCANNED' CHECK (scan_status IN ('NOT_SCANNED', 'CLEAN', 'INFECTED')),
  review_status    text NOT NULL CHECK (review_status IN ('NOT_REQUIRED', 'PENDING', 'VERIFIED', 'REJECTED')),
  reviewed_by      uuid REFERENCES users (id),
  reviewed_by_name text,
  reviewed_at      timestamptz,
  review_reason    text CHECK (review_reason IS NULL OR length(review_reason) <= 500),
  uploaded_by      uuid NOT NULL REFERENCES users (id),
  uploaded_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz,
  purged_at        timestamptz,
  UNIQUE (college_id, id),
  UNIQUE (college_id, student_id, id),
  FOREIGN KEY (college_id, student_id) REFERENCES students (college_id, id),
  CONSTRAINT documents_review_by_kind CHECK ((kind = 'RESUME') = (review_status = 'NOT_REQUIRED')),
  CONSTRAINT documents_reviewed CHECK ((review_status IN ('VERIFIED', 'REJECTED')) = (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
  CONSTRAINT documents_reject_reason CHECK (review_status <> 'REJECTED' OR length(btrim(coalesce(review_reason, ''))) >= 5),
  CONSTRAINT documents_deleted CHECK ((status = 'DELETED') = (deleted_at IS NOT NULL)),
  CONSTRAINT documents_purged CHECK (purged_at IS NULL OR status = 'DELETED')
);
CREATE INDEX documents_student_idx ON documents (student_id, uploaded_at DESC);
CREATE INDEX documents_review_idx ON documents (college_id, review_status) WHERE status = 'ACTIVE';

-- Identity, content fingerprint and key never change; a deleted document is final.
CREATE FUNCTION documents.document_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'document records are retained' USING ERRCODE = '42501'; END IF;
  IF (NEW.college_id, NEW.student_id, NEW.kind, NEW.original_name, NEW.content_type, NEW.size_bytes, NEW.sha256, NEW.storage_key, NEW.uploaded_by, NEW.uploaded_at)
     IS DISTINCT FROM (OLD.college_id, OLD.student_id, OLD.kind, OLD.original_name, OLD.content_type, OLD.size_bytes, OLD.sha256, OLD.storage_key, OLD.uploaded_by, OLD.uploaded_at) THEN
    RAISE EXCEPTION 'document identity and content details are immutable' USING ERRCODE = '42501';
  END IF;
  IF OLD.status = 'DELETED' AND (NEW.status, NEW.deleted_at, NEW.review_status, NEW.reviewed_by, NEW.reviewed_at, NEW.review_reason) IS DISTINCT FROM (OLD.status, OLD.deleted_at, OLD.review_status, OLD.reviewed_by, OLD.reviewed_at, OLD.review_reason) THEN
    RAISE EXCEPTION 'a deleted document cannot be changed' USING ERRCODE = '42501';
  END IF;
  IF OLD.review_status IN ('VERIFIED', 'REJECTED') AND NEW.review_status <> OLD.review_status THEN RAISE EXCEPTION 'a reviewed document cannot be re-reviewed' USING ERRCODE = '42501'; END IF;
  IF OLD.review_status = 'NOT_REQUIRED' AND NEW.review_status <> 'NOT_REQUIRED' THEN RAISE EXCEPTION 'illegal review transition' USING ERRCODE = '42501'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER documents_guard BEFORE UPDATE OR DELETE ON documents FOR EACH ROW EXECUTE FUNCTION documents.document_guard();

CREATE TABLE document_events (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  college_id    uuid NOT NULL,
  document_id   uuid NOT NULL,
  event         text NOT NULL CHECK (event IN ('UPLOADED', 'DELETED', 'VERIFIED', 'REJECTED', 'ACCESSED')),
  actor_user_id uuid NOT NULL REFERENCES users (id),
  actor_role    text NOT NULL,
  actor_name    text NOT NULL,
  detail        text CHECK (detail IS NULL OR length(detail) <= 500),
  occurred_at   timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (college_id, document_id) REFERENCES documents (college_id, id)
);
CREATE INDEX document_events_doc_idx ON document_events (document_id, occurred_at);
CREATE FUNCTION documents.events_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'document history is append-only' USING ERRCODE = '42501'; END $$;
CREATE TRIGGER document_events_no_change BEFORE UPDATE OR DELETE ON document_events FOR EACH ROW EXECUTE FUNCTION documents.events_immutable();
CREATE TRIGGER document_events_no_truncate BEFORE TRUNCATE ON document_events FOR EACH STATEMENT EXECUTE FUNCTION documents.events_immutable();

-- Documents a student attached to an academic submission as evidence (same student by construction, via composite FKs).
CREATE TABLE academic_submission_documents (
  college_id    uuid NOT NULL,
  student_id    uuid NOT NULL,
  submission_id uuid NOT NULL,
  document_id   uuid NOT NULL,
  PRIMARY KEY (submission_id, document_id),
  FOREIGN KEY (college_id, student_id, submission_id) REFERENCES academic_submissions (college_id, student_id, id),
  FOREIGN KEY (college_id, student_id, document_id) REFERENCES documents (college_id, student_id, id)
);
CREATE INDEX asd_document_idx ON academic_submission_documents (document_id);

-- ───────────── privileges + RLS ─────────────
GRANT SELECT, INSERT, UPDATE ON documents TO cc_auth;
GRANT SELECT, INSERT ON document_events, academic_submission_documents TO cc_auth;
GRANT SELECT (id, college_id, student_id, kind, original_name, content_type, size_bytes, sha256, status, scan_status, review_status, reviewed_by_name, reviewed_at, review_reason, uploaded_at, deleted_at)
  ON documents TO cc_app;                                  -- NOT storage_key: the app reads it only through documents.storage_key_for()
GRANT SELECT ON document_events, academic_submission_documents TO cc_app;

ALTER TABLE documents                     ENABLE ROW LEVEL SECURITY; ALTER TABLE documents                     FORCE ROW LEVEL SECURITY;
ALTER TABLE document_events               ENABLE ROW LEVEL SECURITY; ALTER TABLE document_events               FORCE ROW LEVEL SECURITY;
ALTER TABLE academic_submission_documents ENABLE ROW LEVEL SECURITY; ALTER TABLE academic_submission_documents FORCE ROW LEVEL SECURITY;

-- A student sees their own documents (including deleted ones, as history). A coordinator sees only ACTIVE mark sheets, certificates and
-- other documents of students in their CURRENT departments — never resumes. Administrators, officers and the platform see none.
CREATE POLICY documents_select_student ON documents FOR SELECT TO cc_app
  USING (college_id = (SELECT app.current_college_id()) AND (SELECT app.current_role()) = 'STUDENT' AND student_id IN (SELECT st.id FROM students st));
CREATE POLICY documents_select_coordinator ON documents FOR SELECT TO cc_app
  USING (college_id = (SELECT app.current_college_id()) AND (SELECT app.current_role()) = 'COORDINATOR' AND status = 'ACTIVE' AND kind <> 'RESUME'
         AND student_id IN (SELECT st.id FROM students st));
CREATE POLICY document_events_select ON document_events FOR SELECT TO cc_app
  USING (college_id = (SELECT app.current_college_id()) AND document_id IN (SELECT d.id FROM documents d));
CREATE POLICY asd_select ON academic_submission_documents FOR SELECT TO cc_app
  USING (college_id = (SELECT app.current_college_id()) AND submission_id IN (SELECT a.id FROM academic_submissions a)
         AND document_id IN (SELECT d.id FROM documents d));

-- ───────────── functions ─────────────
CREATE FUNCTION documents.event(p_doc uuid, p_college uuid, p_event text, p_detail text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE v_user uuid := app.current_user_id(); v_name text;
BEGIN
  SELECT full_name INTO v_name FROM users WHERE id = v_user;
  INSERT INTO document_events (college_id, document_id, event, actor_user_id, actor_role, actor_name, detail) VALUES (p_college, p_doc, p_event, v_user, app.current_role(), v_name, p_detail);
END $$;

CREATE FUNCTION documents.register(p_kind text, p_name text, p_type text, p_size int, p_sha256 text, p_key text) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE v_user uuid := app.current_user_id(); v_c uuid := app.current_college_id(); v_sid uuid; v_id uuid; v_active int;
BEGIN
  IF app.current_role() IS DISTINCT FROM 'STUDENT' THEN RAISE EXCEPTION 'students only' USING ERRCODE = '42501'; END IF;
  SELECT id INTO v_sid FROM students WHERE user_id = v_user AND college_id = v_c FOR UPDATE;      -- serialises this student's uploads
  IF NOT FOUND THEN RAISE EXCEPTION 'student record not found' USING ERRCODE = '22023'; END IF;
  -- The key must be exactly the one the server derives from this student's own identifiers: one student can never register another's object.
  IF p_key !~ ('^c/' || v_c::text || '/s/' || v_sid::text || '/[0-9a-f-]{36}$') THEN RAISE EXCEPTION 'invalid storage key' USING ERRCODE = '22023'; END IF;
  SELECT count(*) INTO v_active FROM documents WHERE student_id = v_sid AND status = 'ACTIVE';
  IF v_active >= 25 THEN RAISE EXCEPTION 'You can keep at most 25 documents. Delete one you no longer need.' USING ERRCODE = '22023'; END IF;
  INSERT INTO documents (college_id, student_id, kind, original_name, content_type, size_bytes, sha256, storage_key, review_status, uploaded_by)
  VALUES (v_c, v_sid, p_kind, p_name, p_type, p_size, p_sha256, p_key, CASE WHEN p_kind = 'RESUME' THEN 'NOT_REQUIRED' ELSE 'PENDING' END, v_user)
  RETURNING id INTO v_id;
  PERFORM documents.event(v_id, v_c, 'UPLOADED', p_kind);
  PERFORM auth.write_audit('COLLEGE', v_c, v_user, 'STUDENT', 'DOCUMENT_UPLOADED', 'document', v_id::text, jsonb_build_object('kind', p_kind), NULL);
  RETURN v_id;
EXCEPTION WHEN check_violation THEN
  RAISE EXCEPTION 'The file details were not accepted (kind, type, size or name).' USING ERRCODE = '22023';
END $$;

-- Returns the storage key after an explicit authorisation check, logging non-owner access. This is the ONLY way the app obtains a key.
CREATE FUNCTION documents.storage_key_for(p_doc uuid) RETURNS TABLE (storage_key text, content_type text, original_name text)
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE v_user uuid := app.current_user_id(); v_c uuid := app.current_college_id(); v_role text := app.current_role(); d documents%ROWTYPE; v_owner boolean;
BEGIN
  SELECT * INTO d FROM documents WHERE id = p_doc AND college_id = v_c;
  IF NOT FOUND OR v_role IS NULL THEN RAISE EXCEPTION 'document not found' USING ERRCODE = '22023'; END IF;
  IF d.status <> 'ACTIVE' THEN RAISE EXCEPTION 'document not found' USING ERRCODE = '22023'; END IF;
  v_owner := EXISTS (SELECT 1 FROM students WHERE id = d.student_id AND user_id = v_user);
  IF v_role = 'STUDENT' THEN
    IF NOT v_owner THEN RAISE EXCEPTION 'document not found' USING ERRCODE = '22023'; END IF;
  ELSIF v_role = 'COORDINATOR' THEN
    IF d.kind = 'RESUME' OR NOT EXISTS (SELECT 1 FROM students st JOIN coordinator_assignments ca ON ca.department_id = st.department_id AND ca.college_id = st.college_id
                                         WHERE st.id = d.student_id AND ca.user_id = v_user AND ca.ended_at IS NULL) THEN
      RAISE EXCEPTION 'document not found' USING ERRCODE = '22023';
    END IF;
  ELSE
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT v_owner THEN PERFORM documents.event(p_doc, v_c, 'ACCESSED', NULL); END IF;
  RETURN QUERY SELECT d.storage_key, d.content_type, d.original_name;
END $$;

-- Student deletes their own document. Evidence attached to any academic submission cannot be deleted. Returns the key so the app can remove the object.
CREATE FUNCTION documents.delete_document(p_doc uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE v_user uuid := app.current_user_id(); v_c uuid := app.current_college_id(); d documents%ROWTYPE;
BEGIN
  IF app.current_role() IS DISTINCT FROM 'STUDENT' THEN RAISE EXCEPTION 'students only' USING ERRCODE = '42501'; END IF;
  SELECT x.* INTO d FROM documents x WHERE x.id = p_doc AND x.college_id = v_c AND x.status = 'ACTIVE'
     AND x.student_id = (SELECT st.id FROM students st WHERE st.user_id = v_user AND st.college_id = v_c) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'document not found' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM academic_submission_documents WHERE document_id = p_doc) THEN
    RAISE EXCEPTION 'This document is attached as evidence to an academic submission and cannot be deleted.' USING ERRCODE = '22023';
  END IF;
  UPDATE documents SET status = 'DELETED', deleted_at = now() WHERE id = p_doc;
  PERFORM documents.event(p_doc, v_c, 'DELETED', NULL);
  PERFORM auth.write_audit('COLLEGE', v_c, v_user, 'STUDENT', 'DOCUMENT_DELETED', 'document', p_doc::text, jsonb_build_object('kind', d.kind), NULL);
  RETURN d.storage_key;
END $$;

CREATE FUNCTION documents.mark_purged(p_doc uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
  IF app.current_role() IS DISTINCT FROM 'STUDENT' THEN RAISE EXCEPTION 'students only' USING ERRCODE = '42501'; END IF;
  UPDATE documents SET purged_at = now() WHERE id = p_doc AND status = 'DELETED' AND purged_at IS NULL
     AND student_id = (SELECT st.id FROM students st WHERE st.user_id = app.current_user_id());
END $$;

-- A coordinator of the student's department verifies or rejects a pending mark sheet / certificate / other document.
CREATE FUNCTION documents.review(p_doc uuid, p_decision text, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE v_user uuid := app.current_user_id(); v_c uuid := app.current_college_id(); d documents%ROWTYPE; v_name text;
BEGIN
  IF app.current_role() IS DISTINCT FROM 'COORDINATOR' THEN RAISE EXCEPTION 'only a department coordinator can review documents' USING ERRCODE = '42501'; END IF;
  IF p_decision NOT IN ('VERIFIED', 'REJECTED') THEN RAISE EXCEPTION 'invalid decision' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'REJECTED' AND (p_reason IS NULL OR length(btrim(p_reason)) < 5 OR length(p_reason) > 500) THEN RAISE EXCEPTION 'A reason of 5-500 characters is required.' USING ERRCODE = '22023'; END IF;
  SELECT x.* INTO d FROM documents x WHERE x.id = p_doc AND x.college_id = v_c FOR UPDATE;
  IF NOT FOUND OR d.kind = 'RESUME' THEN RAISE EXCEPTION 'document not found' USING ERRCODE = '22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM students st JOIN coordinator_assignments ca ON ca.department_id = st.department_id AND ca.college_id = st.college_id
                  WHERE st.id = d.student_id AND ca.user_id = v_user AND ca.ended_at IS NULL) THEN RAISE EXCEPTION 'not authorized for this student''s department' USING ERRCODE = '42501'; END IF;
  IF d.status <> 'ACTIVE' OR d.review_status <> 'PENDING' THEN RAISE EXCEPTION 'This document is not awaiting review.' USING ERRCODE = '22023'; END IF;
  SELECT full_name INTO v_name FROM users WHERE id = v_user;
  UPDATE documents SET review_status = p_decision, reviewed_by = v_user, reviewed_by_name = v_name, reviewed_at = now(), review_reason = nullif(btrim(coalesce(p_reason, '')), '') WHERE id = p_doc;
  PERFORM documents.event(p_doc, v_c, p_decision, nullif(btrim(coalesce(p_reason, '')), ''));
  PERFORM auth.write_audit('COLLEGE', v_c, v_user, 'COORDINATOR', 'DOCUMENT_' || p_decision, 'document', p_doc::text, jsonb_build_object('kind', d.kind), NULL);
END $$;

-- ───────────── ownership + execute privileges ─────────────
DO $$
DECLARE f record;
BEGIN
  FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
            WHERE n.nspname = 'documents' AND p.proname NOT IN ('document_guard', 'events_immutable') LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO cc_auth', f.sig);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f.sig);
  END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION documents.register(text, text, text, int, text, text), documents.storage_key_for(uuid), documents.delete_document(uuid),
                          documents.mark_purged(uuid), documents.review(uuid, text, text) TO cc_app;
-- documents.event is internal.

-- ───────────── academics.submit gains evidence documents (replaces the Phase 5 function; owner cc_auth) ─────────────
SET LOCAL ROLE cc_auth;
DROP FUNCTION academics.submit(numeric, numeric, numeric, numeric, int, int, text);
CREATE FUNCTION academics.submit(p_cgpa numeric, p_tenth numeric, p_twelfth numeric, p_diploma numeric, p_backlogs int, p_arrears int, p_note text, p_document_ids uuid[] DEFAULT '{}') RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE v_user uuid := app.current_user_id(); v_c uuid := app.current_college_id(); v_s students%ROWTYPE; v_ver int; v_id uuid; v_cur academic_submissions%ROWTYPE; v_docs uuid[] := coalesce(p_document_ids, '{}');
BEGIN
  IF app.current_role() IS DISTINCT FROM 'STUDENT' THEN RAISE EXCEPTION 'students only' USING ERRCODE = '42501'; END IF;
  PERFORM academics.check_values(p_cgpa, p_tenth, p_twelfth, p_diploma, p_backlogs, p_arrears, p_note);
  IF coalesce(array_length(v_docs, 1), 0) > 10 THEN RAISE EXCEPTION 'Attach at most 10 documents.' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_s FROM students WHERE user_id = v_user AND college_id = v_c FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'student record not found' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM academic_submissions WHERE student_id = v_s.id AND status = 'SUBMITTED') THEN
    RAISE EXCEPTION 'You already have a submission awaiting review. Withdraw it to submit a different one.' USING ERRCODE = '23505';
  END IF;
  SELECT * INTO v_cur FROM academic_submissions WHERE student_id = v_s.id AND status = 'VERIFIED';
  IF FOUND AND (v_cur.cgpa, v_cur.tenth_percentage, v_cur.twelfth_percentage, v_cur.diploma_percentage, v_cur.active_backlogs, v_cur.historical_arrears)
               IS NOT DISTINCT FROM (p_cgpa, p_tenth, p_twelfth, p_diploma, p_backlogs, p_arrears) THEN
    RAISE EXCEPTION 'These values are identical to your verified record; there is nothing to update.' USING ERRCODE = '22023';
  END IF;
  IF (SELECT count(DISTINCT x) FROM unnest(v_docs) AS x) <> coalesce(array_length(v_docs, 1), 0)
     OR (SELECT count(*) FROM documents d WHERE d.id = ANY (v_docs) AND d.student_id = v_s.id AND d.college_id = v_c AND d.status = 'ACTIVE' AND d.kind IN ('MARKSHEET', 'CERTIFICATE')) <> coalesce(array_length(v_docs, 1), 0) THEN
    RAISE EXCEPTION 'Evidence must be your own uploaded mark sheets or certificates that have not been deleted.' USING ERRCODE = '22023';
  END IF;
  SELECT coalesce(max(version), 0) + 1 INTO v_ver FROM academic_submissions WHERE student_id = v_s.id;
  INSERT INTO academic_submissions (college_id, student_id, version, cgpa, tenth_percentage, twelfth_percentage, diploma_percentage, active_backlogs, historical_arrears, student_note,
                                    degree, department_id, passing_year, submitted_by)
  VALUES (v_c, v_s.id, v_ver, p_cgpa, p_tenth, p_twelfth, p_diploma, p_backlogs, p_arrears, nullif(btrim(coalesce(p_note, '')), ''), v_s.degree, v_s.department_id, v_s.passing_year, v_user)
  RETURNING id INTO v_id;
  INSERT INTO academic_submission_documents (college_id, student_id, submission_id, document_id) SELECT v_c, v_s.id, v_id, x FROM unnest(v_docs) AS x;
  PERFORM auth.write_audit('COLLEGE', v_c, v_user, 'STUDENT', 'ACADEMICS_SUBMITTED', 'academic_submission', v_id::text, jsonb_build_object('version', v_ver, 'evidence', coalesce(array_length(v_docs, 1), 0)), NULL);
  RETURN v_id;
END $$;
REVOKE ALL ON FUNCTION academics.submit(numeric, numeric, numeric, numeric, int, int, text, uuid[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION academics.submit(numeric, numeric, numeric, numeric, int, int, text, uuid[]) TO cc_app;
RESET ROLE;
REVOKE CREATE ON SCHEMA academics FROM cc_auth;
REVOKE CREATE ON SCHEMA documents FROM cc_auth;
